@props(['id','title','icon'=>'grid','items'=>[]])
@php($active=collect($items)->contains(fn($item)=>request()->routeIs($item[0])))
<section class="nav-group {{ $active?'is-open':'' }}" data-nav-group="{{ $id }}"><button class="nav-group-toggle" type="button" data-nav-toggle aria-expanded="{{ $active?'true':'false' }}" aria-controls="nav-group-{{ $id }}"><x-icon :name="$icon" size="18"/><span>{{ $title }}</span><x-icon name="chevron" size="13"/></button><div id="nav-group-{{ $id }}" class="nav-group-panel" @if(!$active) inert @endif><div class="nav-group-inner">@foreach($items as [$route,$itemIcon,$label])<a href="{{ route($route) }}" class="nav-item nav-subitem {{ request()->routeIs($route)?'selected':'' }}" aria-label="{{ $label }}" title="{{ $label }}"><x-icon :name="$itemIcon" size="15"/><span>{{ $label }}</span>@if(request()->routeIs($route))<span class="nav-indicator"></span>@endif</a>@endforeach</div></div></section>
